describe('In-App Notifications Real-Time Update', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display new notifications in real-time without page refresh', () => {
    // Intercept the initial notification fetch
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Verify initial notification count is 0
    cy.get('[data-testid="notification-badge"]').should('contain', '0');
    cy.get('[data-testid="notification-list"]').should('be.visible');

    // Intercept the real-time notification push
    cy.intercept('POST', '/api/notifications/push').as('pushNotification');

    // Trigger a new notification via API call
    cy.request('POST', '/api/notifications/push', {
      message: 'New message received',
      type: 'message'
    }).as('newNotification');

    // Wait for the push notification to be processed
    cy.wait('@newNotification');

    // Verify notification badge updates in real-time
    cy.get('[data-testid="notification-badge"]').should('contain', '1');

    // Verify notification appears in the list without page reload
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'New message received');

    // Verify notification has correct styling
    cy.get('[data-testid="notification-item"]').should('have.class', 'notification-unread');
  });

  it('should handle multiple real-time notifications and mark them as read', () => {
    // Intercept initial fetch
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

    // Intercept multiple push notifications
    cy.intercept('POST', '/api/notifications/push').as('pushNotification1');
    cy.intercept('POST', '/api/notifications/push').as('pushNotification2');

    // Trigger first notification
    cy.request('POST', '/api/notifications/push', {
      message: 'First alert',
      type: 'alert'
    }).as('notification1');
    cy.wait('@notification1');

    // Verify first notification appears
    cy.get('[data-testid="notification-badge"]').should('contain', '1');
    cy.get('[data-testid="notification-item"]').should('contain', 'First alert');

    // Trigger second notification
    cy.request('POST', '/api/notifications/push', {
      message: 'Second alert',
      type: 'alert'
    }).as('notification2');
    cy.wait('@notification2');

    // Verify notification badge updates to 2
    cy.get('[data-testid="notification-badge"]').should('contain', '2');
    cy.get('[data-testid="notification-item"]').should('have.length', 2);

    // Click on the first notification to mark as read
    cy.get('[data-testid="notification-item"]').first().click();

    // Verify notification is marked as read
    cy.get('[data-testid="notification-item"]').first().should('have.class', 'notification-read');

    // Verify badge count decreases
    cy.get('[data-testid="notification-badge"]').should('contain', '1');
  });
});
